#!/data/data/com.termux/files/usr/bin/bash
#
# Termux smoke suite for proot-distro-i18n.
#
# Runs INSIDE the termux/termux-docker:aarch64 container (native arm64
# CI runner), with the repo mounted read-only at /work and /tmp mounted
# as a read-only tmpfs -- the host-side equivalent of the Android
# layout this fork exists for: no writable /tmp, so every proot temp
# path must fall back to $PREFIX/tmp.
#
# EXPECTED_HASH must carry the git describe-style short hash of the
# checked-out commit (git rev-parse --short=8 HEAD).

set -u

# The upstream termux/termux-docker image no longer guarantees a
# preinstalled python3 (observed 2026-11-07: a fresh aarch64 image
# shipped without it and 13 of 14 checks died on "python3: command
# not found" before anything under test was reached).  Install it on
# demand; a no-op when it is already there.
command -v python3 >/dev/null 2>&1 || {
    echo "== python3 missing from the base image: pkg install python =="
    pkg install -y python || apt install -y python
}

PREFIX=/data/data/com.termux/files/usr
LOG=$PREFIX/tmp
mkdir -p "$LOG"
PASS=0
FAIL=0
ok()  { PASS=$((PASS+1)); echo "[PASS] $1"; }
bad() { FAIL=$((FAIL+1)); echo "[FAIL] $1"; }
PD() { python3 /work/proot-distro.py "$@"; }

# The image entrypoint drops privileges to the system user through a
# whitelist of env vars -- EXPECTED_HASH does not survive it -- so the
# workflow passes the hash as the first argument; the environment stays
# as the fallback for local runs.
EXPECTED_HASH=${1:-${EXPECTED_HASH:-}}

# Pin the UI language to English so the grep assertions below are
# stable (the repo's own pytest suite pins it the same way via
# conftest). `lang get` in T4c proves the language machinery itself.
export PD_LANG=en
export PD_BUILD_HASH="$EXPECTED_HASH"
# Pin the official registry: the fork defaults to a mirror when no
# config exists, and mirrors 401 on images they have not cached --
# exactly what T5a must not depend on.
export PD_REGISTRY_URL="https://registry-1.docker.io"

echo "== T0: this really is the Termux environment =="
if [ -x "$PREFIX/bin/sh" ] && [ -x /system/bin/linker64 ]; then
    ok T0
else
    bad T0
fi

echo "== T1: bootstrap runtime (python + proot from the Termux repo) =="
# pkg's mirror auto-picker has landed on dead community mirrors before
# (the 401/InRelease flake); pin the official Termux mirror and retry,
# so the bootstrap does not depend on mirror roulette.  The success
# test is the binaries themselves, not the exit status.
if [ -w "$PREFIX/etc/apt" ]; then
    echo "deb https://packages.termux.dev/apt/termux-main stable main" \
        > "$PREFIX/etc/apt/sources.list"
fi
attempts=0
until pkg update -y >>"$LOG/pkg.log" 2>&1 \
      && pkg install -y python proot >>"$LOG/pkg.log" 2>&1; do
    attempts=$((attempts + 1))
    [ "$attempts" -ge 3 ] && break
    sleep 5
done
if command -v python3 >/dev/null 2>&1 \
   && command -v proot >/dev/null 2>&1; then
    ok T1
else
    bad T1
    tail -20 "$LOG/pkg.log"
fi

echo "== T2: pd version shows the build hash and the runtime =="
V=$(PD version)
echo "$V"
printf '%s\n' "$V" | grep -q "(build $EXPECTED_HASH)" && ok T2a || bad T2a
printf '%s\n' "$V" | grep -q "runtime.*proot" && ok T2b || bad T2b

echo "== T3: pd --version / -V route to the same block =="
PD --version | grep -q "(build $EXPECTED_HASH)" && ok T3a || bad T3a
PD -V | grep -q "(build $EXPECTED_HASH)" && ok T3b || bad T3b
PD v | grep -q "(build $EXPECTED_HASH)" && ok T3c || bad T3c

echo "== T4: help, list, lang render =="
PD help >/dev/null 2>&1 && ok T4a || bad T4a
PD list >/dev/null 2>&1 && ok T4b || bad T4b
PD lang get >/dev/null 2>&1 && ok T4c || bad T4c

echo "== T5: end-to-end — install alpine and log in (read-only /tmp) =="
if PD install alpine >"$LOG/install.log" 2>&1; then
    ok T5a
else
    bad T5a
    tail -30 "$LOG/install.log"
fi
OUT=$(PD login alpine -- cat /etc/os-release 2>"$LOG/login.err")
printf '%s\n' "$OUT" | grep -q "ID=alpine" \
    && ok T5b || { bad T5b; tail -30 "$LOG/login.err"; }
OUT=$(PD login alpine -- sh -c 'echo E2E-OK')
printf '%s\n' "$OUT" | grep -q "E2E-OK" && ok T5c || bad T5c

echo "== T6: runtime line reflects PD_PROOT_BIN override =="
OUT=$(PD_PROOT_BIN="$PREFIX/bin/proot" PD version)
printf '%s\n' "$OUT" | grep -q "PD_PROOT_BIN" && ok T6 || bad T6

# T7: the on-device bug reports that motivated the 5.10.5 sweep, each
# re-verified where CI can actually reach it.  The guest keeps its
# alpine install from T5 for these.
echo "== T7a: resolv.conf is managed and carries reachable nameservers =="
OUT=$(PD login alpine -- cat /etc/resolv.conf 2>>"$LOG/login.err")
echo "$OUT"
# The managed marker line or its legacy static template — both prove pd
# wrote it, not the image.
printf '%s\n' "$OUT" | grep -q "^# generated by proot-distro-i18n" \
    && ok T7a1 || bad T7a1
# Nameservers must be present and non-empty.
printf '%s\n' "$OUT" | grep -q "^nameserver " \
    && ok T7a2 || bad T7a2
# 8.8.8.8 was the upstream default that apk/apt could not resolve
# through on CN networks; it must not be the only answer anymore.
if printf '%s\n' "$OUT" | grep -q "^nameserver 8.8.8.8" \
   && ! printf '%s\n' "$OUT" | grep -vq "^nameserver 8.8.8.8" 2>/dev/null; then
    bad T7a3   # only Google DNS — the old failure mode
else
    ok T7a3
fi

echo "== T7b: the app uid resolves to a name (no 'I have no name!') =="
# The Termux docker image drops to a system user whose uid HAS a passwd
# entry; the fallback path (aid_<uid>) is unit-tested.  What CI proves
# here is the end-to-end contract: the guest passwd has an entry whose
# uid matches the invoking uid, so a shell never prints "I have no
# name!".
GUEST_UID=$(PD login alpine -- sh -c 'id -u' 2>>"$LOG/login.err")
OUT=$(PD login alpine -- sh -c 'id -un' 2>>"$LOG/login.err")
echo "guest uid=$GUEST_UID name=$OUT"
[ -n "$OUT" ] && [ "$OUT" != "I have no name!" ] && [ "$OUT" != "nobody" ] \
    && ok T7b || bad T7b

echo "== T7c: DNS actually resolves inside the guest =="
# The real on-device failure: DNS queries dying inside the guest.
# nslookup is busybox's, present in the alpine image.
OUT=$(PD login alpine -- sh -c \
      'nslookup mirrors.tuna.tsinghua.edu.cn 2>&1 | tail -3' \
      2>>"$LOG/login.err")
echo "$OUT"
printf '%s\n' "$OUT" | grep -qi "address\|answer" \
    && ok T7c || { bad T7c
                   # diag: which nameservers did the guest try?
                   PD login alpine -- cat /etc/resolv.conf 2>/dev/null; }

echo "== T7d: mirror distro switches alpine to the default TUNA mirror =="
if PD mirror distro alpine >"$LOG/mirror.log" 2>&1; then
    ok T7d1
else
    bad T7d1
    tail -20 "$LOG/mirror.log"
fi
OUT=$(PD login alpine -- cat /etc/apk/repositories 2>>"$LOG/login.err")
echo "$OUT"
printf '%s\n' "$OUT" | grep -q "mirrors.tuna.tsinghua.edu.cn/alpine" \
    && ok T7d2 || bad T7d2
# Round trip: --revert must succeed and restore dl-cdn.
PD mirror distro alpine --revert >>"$LOG/mirror.log" 2>&1 \
    && ok T7d3 || bad T7d3
OUT=$(PD login alpine -- cat /etc/apk/repositories 2>>"$LOG/login.err")
printf '%s\n' "$OUT" | grep -q "dl-cdn.alpinelinux.org" \
    && ok T7d4 || bad T7d4

echo "== T7e: mirror distro --mirror picks the named provider =="
if PD mirror distro alpine --mirror ustc >>"$LOG/mirror.log" 2>&1; then
    ok T7e1
else
    bad T7e1
    tail -20 "$LOG/mirror.log"
fi
OUT=$(PD login alpine -- cat /etc/apk/repositories 2>>"$LOG/login.err")
echo "$OUT"
printf '%s\n' "$OUT" | grep -q "mirrors.ustc.edu.cn/alpine" \
    && ok T7e2 || bad T7e2

echo "== T7f: apk update through the switched mirror (DNS end to end) =="
# The original bug report: `apk update` failing with
# 'DNS: transient error (try again later)'. With a switched CN mirror
# (whatever T7e left in place) and the managed resolv.conf this must
# now succeed.  A non-DNS failure (offline runner) is environment, not
# a regression.
if OUT=$(PD login alpine -- apk update 2>&1); then
    ok T7f
else
    echo "$OUT"
    echo "$OUT" | grep -qi "dns\|temporary failure\|try again" \
        && bad T7f || ok T7f
fi

PD rm alpine >/dev/null 2>&1 || true

# T8: debian (glibc) — the on-device repro surface the smoke never
# reached. T5-T7 run alpine/musl only: musl answers getpwuid straight
# from /etc/passwd, while glibc walks NSS, which is exactly where the
# real-device report ("I have no name!" from a debian guest) lives.
# The on-device symptom was on an *old* install — pd update refreshes
# binaries, never the rootfs — so the heal must be proven here too.
echo "== T8a: install debian (glibc; the on-device repro surface) =="
if PD install debian >"$LOG/debian-install.log" 2>&1; then
    ok T8a
else
    bad T8a
    tail -30 "$LOG/debian-install.log"
fi

DEBIAN_ROOTFS="$PREFIX/var/lib/proot-distro/containers/debian/rootfs"

echo "== T8b: no 'I have no name!' in a glibc guest =="
OUT=$(PD login debian -- sh -c 'id -un' 2>>"$LOG/login.err")
echo "debian guest name=$OUT"
[ -n "$OUT" ] && [ "$OUT" != "I have no name!" ] \
    && ok T8b || bad T8b

echo "== T8c: the login-time heal repairs a damaged passwd =="
# Simulate a legacy container: the root line and the Termux uid line
# are both gone (what pre-5.10.5 devices ended up with). The next
# login must put them back, or whoami keeps failing.
if [ -f "$DEBIAN_ROOTFS/etc/passwd" ]; then
    GUEST_UID=$(PD login debian -- sh -c 'id -u' 2>>"$LOG/login.err")
    awk -F: -v u="$GUEST_UID" '$1 != "root" && $3 != u' \
        "$DEBIAN_ROOTFS/etc/passwd" > "$DEBIAN_ROOTFS/etc/passwd.new" \
        && mv "$DEBIAN_ROOTFS/etc/passwd.new" "$DEBIAN_ROOTFS/etc/passwd"
    OUT=$(PD login debian -- sh -c 'id -un' 2>>"$LOG/login.err")
    echo "after damage: name=$OUT"
    [ -n "$OUT" ] && [ "$OUT" != "I have no name!" ] \
        && ok T8c || bad T8c
else
    bad T8c   # rootfs not where the runtime says it is: no real heal ran
fi

echo "== T8d: apt update inside the glibc guest (DNS end to end) =="
# The on-device report was apt failing inside debian; same judgement
# as T7f: an environment-level network failure on the runner is not a
# regression.
if OUT=$(PD login debian -- apt-get update 2>&1); then
    ok T8d
else
    echo "$OUT" | tail -10
    echo "$OUT" | grep -qi "temporary failure\|network is unreachable\|could not resolve" \
        && ok T8d || bad T8d
fi

PD rm debian >/dev/null 2>&1 || true

echo
echo "RESULT: PASS=$PASS FAIL=$FAIL"
[ "$FAIL" = 0 ]
